/// <summary>
/// MPJ_24248 Pricing Data Extract
/// Track changes related to prices and add entry to Price Change tracking table for later processing
/// </summary>
using Microsoft.Dynamics.AX.Platform.Extensibility;
[ExportInterface()]
abstract class METPriceChangeEvent
{
    METPriceChangeTracking  priceChangeTracking;
    TransDate               todayDate;
    const public str        blankValue = '';
    SysAppCRUDOperation     sourceCrud;

}

Method.Source:
/// <summary>
/// Initialise the instance for a Source record
/// </summary>
/// <param name = "_Common">Table record</param>
abstract void initInstance(Common _Common, SysAppCRUDOperation _crud)
{
}

/// <summary>
/// Process the Source record that triggered the change
/// </summary>
abstract void process()
{
}

/// <summary>
/// Get the Price change type
/// </summary>
/// <returns>the proce change type</returns>
abstract METPriceChangeType getPriceChangeType()
{

}

    /// <summary>
    /// Get the number sequence id
    /// </summary>
    /// <returns>the number sequence number</returns>
    public METPriceChangeTrackingId getNumberSeq()
    {
        NumberSequenceReference     numberSequenceReference;
        NumberSeq                   numberSeq;

        numberSequenceReference = GUPParameters::numRefMETPriceChangeTrackingId();
        
        if (numberSequenceReference)
        {
            numberSeq = NumberSeq::newGetNum(numberSequenceReference);
        }

        if(!numberSeq)
        {
            error("@MET:ChangeTrackNumberIdNumSeqFailed");
            throw Exception::Error;
        }

        return str2Int(numberSeq.num());
    }

/// <summary>
/// Set common values for a new priceChangeTracking record
/// </summary>
/// <param name = "_common">Table record</param>
public void setCommonValues(Common _common)
{
    priceChangeTracking.SourceCrud  = sourceCrud;
    priceChangeTracking.ChangeType  = this.getPriceChangeType();
    priceChangeTracking.TrackingId  = this.getNumberSeq();
    priceChangeTracking.RefRecId    = _common.recId;
    priceChangeTracking.RefTableId  = _common.tableId;
}

/// <summary>
/// get an inventory dimension id for
/// </summary>
/// <param name = "_inventSiteId">Site</param>
/// <returns>Inventory dimension id</returns>
public inventDimId getInventDimIdFromSite(InventSiteId _inventSiteId)
{   
    InventDim   inventDim;
    
    inventDim.clear();
    inventDim.InventSiteId = _inventSiteId;
    
    return InventDim::FindOrCreate(inventDim).inventDimId;
}

/// <summary>
/// Set internal variables
/// </summary>
/// <param name = "_common">Table record</param>
public void setInternals(Common _common, SysAppCRUDOperation _crud)
{
    todayDate = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimezone());
    sourceCrud = _crud;
}
